const email = $('Prep New User').item.json.email;
const rows = ($json.body?.rows || []);
const match = rows.find(r => String(r.email||'').toLowerCase() === String(email||'').toLowerCase());
if (match && match.id) {
  return [{ json: {
    email,
    first_name: $('Prep New User').item.json.first_name,
    last_name: $('Prep New User').item.json.last_name,
    snipe_user_id: match.id,
    created_user: false,
  }}];
}
return [{ json: {
  email,
  first_name: $('Prep New User').item.json.first_name,
  last_name: $('Prep New User').item.json.last_name,
  snipe_user_id: '',
  created_user: false,
}}];

const payload = $input.first().json.payload;
if (!payload) return [];
const rows = Array.isArray(payload) ? payload : JSON.parse(payload);
return rows.map(r => ({
  json: {
    email: String(r.email||'').toLowerCase(),
    first_name: r.first_name || '',
    last_name: r.last_name || '',
    username: String(r.username || r.email.split('@')[0] || '').slice(0,100),
    password: 'Aa9!' + Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2),
  }
}));

const baseUrl = `${$env.SNIPE_HOST}/api/v1/users?limit=500`;
const allRows = [];
for (let offset = 0; offset < 3000; offset += 500) {
  const url = `${baseUrl}&offset=${offset}`;
  try {
    const resp = await this.helpers.httpRequestWithAuthentication.call(this, 'httpBearerAuth', {
      url,
      headers: { Accept: 'application/json' },
      returnFullResponse: true,
    }, { nodeCredentialType: 'httpBearerAuth' });
    const body = resp.body;
    const rows = (body && body.rows) ? body.rows : [];
    allRows.push(...rows);
    if (rows.length < 500) break;
  } catch (e) {
    break;
  }
}
return [{ json: { body: { rows: allRows } } }];

const rows = $input.all().map(i => i.json);
if (rows.length === 0) return [];
const payload = JSON.stringify(rows);
const stats = {
  total: rows.length,
  ok: rows.filter(r => r.status === 'ok').length,
  errores: rows.filter(r => r.status === 'error').length,
  usuarios_nuevos: rows.filter(r => r.status === 'ok' && r.created_user).length,
};
return [{ json: { payload, ...stats } }];

const pkg = $('Package Results').first().json;
const diffCount = (()=>{ try { return $('Detect Changes').all().length; } catch(e){ return 0; } })();
const omitidos = (()=>{ try { return $('Count Unmapped').first().json.omitidos ?? 0; } catch(e){ return 0; } })();
const cambios = diffCount;
const ok = pkg.ok ?? 0;
const errores = pkg.errores ?? 0;
const usuarios_nuevos = pkg.usuarios_nuevos ?? 0;
const summary = { cambios, aplicados: ok, errores, omitidos, usuarios_nuevos };
return [{ json: summary }];

